import React, { useEffect, useState } from 'react';
import axios from 'axios';
import { Container, Row, Col, Card, Spinner } from 'react-bootstrap';
import './EventList.css';

const EventList = () => {
  const [events, setEvents] = useState([]);
  const [loading, setLoading] = useState(true);

  const fetchEvents = async () => {
    const token = localStorage.getItem('authToken');
    console.log("🔍 Token retrieved:", token); // Debugging log
  
    if (!token) {
      console.error("❌ No auth token found. Redirecting to login.");
      return;
    }
  
    try {
      const response = await axios.get('http://localhost:8000/api/events/available', {
        headers: {
          Authorization: `Bearer ${token}`,
        },
      });
      setEvents(response.data);
    } catch (error) {
      console.error('❌ Error fetching events:', error.response?.data || error.message);
    } finally {
      setLoading(false);
    }
  };
  

  useEffect(() => {
    fetchEvents();
  }, []);

  return (
    <Container className="mt-4">
      <h2 className="text-center mb-4">Available Events</h2>
      {loading ? (
        <div className="text-center">
          <Spinner animation="border" variant="info" />
        </div>
      ) : events.length > 0 ? (
        <Row>
          {events.map((event) => (
            <Col key={event._id} md={4} className="mb-4">
              <Card className="event-card">
                <div className="card-image-wrapper">
                  <Card.Img variant="top" src={event.image || 'https://via.placeholder.com/300'} alt={event.title} />
                  <div className="event-overlay">
                    <h5>{event.title}</h5>
                    <p>{event.description}</p>
                    <p>{new Date(event.date).toLocaleDateString()}</p>
                  </div>
                </div>
              </Card>
            </Col>
          ))}
        </Row>
      ) : (
        <p className="text-center">No events available at the moment.</p>
      )}
    </Container>
  );
};

export default EventList;
